mapper.update:
INSERT INTO TBO_CALENDAR(
	FC_SEQ
	,FC_USER
	,FC_TITLE
	,FC_START_DATE
	,FC_END_DATE
	,FC_ALLDAY
	,FC_BG_COLOR
	,FC_REGIST_DATE
) VALUES (
	#{fcSeq}
	,#{fcUser}
	,#{fcTitle}
	,#{fcStartDate}
	,#{fcEndDate}
	,#{fcAllday}
	,#{fcBgColor}
	,DATE_FORMAT(SYSDATE(), '%Y%m%d%H%i%s')
) ON DUPLICATE KEY UPDATE
	FC_USER = #{fcUser}
	,FC_TITLE = #{fcTitle}
	,FC_START_DATE = #{fcStartDate}
	,FC_END_DATE = #{fcEndDate}
	,FC_ALLDAY = #{fcAllday}
	,FC_BG_COLOR = #{fcBgColor}
	,FC_UPDT_DATE = #{fcUpdtDate}
